// --- Brick bounce resolution (issue #1) -------------------------------------

// Resolves a ball that ALREADY overlaps the brick. Per the issue: the face hit
// is the one with the SMALLER penetration (flip `vy` on a top/bottom hit, `vx`
// on a side hit, leave the other component alone); equal penetration on both
// axes means a diagonal corner hit (flip both). The ball is pushed back out of
// the rectangle, otherwise it still overlaps on the next frame and re-flips
// forever (sticky bounce). A velocity is only flipped when the ball is moving
// TOWARD the face it hit, so an overlap the ball is already leaving never
// re-aims it into the brick.
function resolveBrickOverlap(ball, brick) {
  const r = ball.r;
  // Penetration of the ball box past each face of the brick.
  const penLeft = ball.x + r - brick.x; // right edge past the left face
  const penRight = brick.x + brick.w - (ball.x - r); // left edge past the right face
  const penTop = ball.y + r - brick.y; // bottom edge past the top face
  const penBottom = brick.y + brick.h - (ball.y - r); // top edge past the bottom face
  const penX = Math.min(penLeft, penRight);
  const penY = Math.min(penTop, penBottom);
  const EPS = 1e-9;

  if (penX < penY - EPS) {
    // Side hit: bounce on the horizontal axis only.
    if (penLeft < penRight) {
      if (ball.vx > 0) ball.vx = -ball.vx; // hit the left face
      ball.x = brick.x - r;
    } else {
      if (ball.vx < 0) ball.vx = -ball.vx; // hit the right face
      ball.x = brick.x + brick.w + r;
    }
  } else if (penY < penX - EPS) {
    // Top/bottom hit: bounce on the vertical axis only.
    if (penTop < penBottom) {
      if (ball.vy > 0) ball.vy = -ball.vy; // hit the top face
      ball.y = brick.y - r;
    } else {
      if (ball.vy < 0) ball.vy = -ball.vy; // hit the bottom face
      ball.y = brick.y + brick.h + r;
    }
  } else {
    // Corner: equal penetrations — a diagonal hit, flip both components.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = penLeft <= penRight ? brick.x - r : brick.x + brick.w + r;
    ball.y = penTop <= penBottom ? brick.y - r : brick.y + brick.h + r;
  }
}

// Continuous (swept) collision for a fast ball that jumps OVER the brick in a
// single frame (tunnelling, issue #1). Detection is discrete — it samples the
// position before and after the move — so at level 6 a stuttered frame moves
// the ball 35.5 px against 34 px to cross a brick. The centre of the ball is
// swept along the segment from the position at the START of the step to the
// current one, tested against the brick inflated by the ball radius (slab
// method). The face entered is the one whose slab was entered last; the ball
// is pushed back out through that face.
// Returns true when the ball crossed the brick during this step.
function resolveBrickSwept(ball, brick, prevX, prevY) {
  const r = ball.r;
  const minX = brick.x - r;
  const maxX = brick.x + brick.w + r;
  const minY = brick.y - r;
  const maxY = brick.y + brick.h + r;
  const dx = ball.x - prevX;
  const dy = ball.y - prevY;

  let enterX = -Infinity;
  let exitX = Infinity;
  let enterY = -Infinity;
  let exitY = Infinity;

  if (dx === 0) {
    // Moving parallel to the x axis: only reachable when already inside the slab.
    if (prevX <= minX || prevX >= maxX) return false;
  } else {
    let t1 = (minX - prevX) / dx;
    let t2 = (maxX - prevX) / dx;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    enterX = t1;
    exitX = t2;
  }
  if (dy === 0) {
    if (prevY <= minY || prevY >= maxY) return false;
  } else {
    let t1 = (minY - prevY) / dy;
    let t2 = (maxY - prevY) / dy;
    if (t1 > t2) {
      const tmp = t1;
      t1 = t2;
      t2 = tmp;
    }
    enterY = t1;
    exitY = t2;
  }

  const tEnter = Math.max(enterX, enterY);
  const tExit = Math.min(exitX, exitY);
  // The ball must actually CROSS during this step: a negative tEnter means it
  // already overlapped at the start (static case, resolved by collides() above;
  // re-resolving it here would bounce the same seam twice and cancel out).
  if (tEnter < 0 || tEnter > tExit || tEnter > 1 || tExit < 0) return false;

  const EPS = 1e-9;
  if (enterX > enterY + EPS) {
    // Side hit.
    if (dx > 0) {
      ball.vx = -Math.abs(ball.vx); // came from the left, through the left face
      ball.x = brick.x - r;
    } else {
      ball.vx = Math.abs(ball.vx); // came from the right, through the right face
      ball.x = brick.x + brick.w + r;
    }
  } else if (enterY > enterX + EPS) {
    // Top/bottom hit.
    if (dy > 0) {
      ball.vy = -Math.abs(ball.vy); // came from above, through the top face
      ball.y = brick.y - r;
    } else {
      ball.vy = Math.abs(ball.vy); // came from below, through the bottom face
      ball.y = brick.y + brick.h + r;
    }
  } else {
    // Diagonal hit straight through a corner: flip both.
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    ball.x = dx >= 0 ? brick.x - r : brick.x + brick.w + r;
    ball.y = dy >= 0 ? brick.y - r : brick.y + brick.h + r;
  }
  return true;
}

