  // Bricks: bounce, destroy, score. A ball that overlaps a brick is resolved
  // by penetration (which face was hit); a fast ball that jumped over a brick
  // in this single step is caught by sweeping between the previous and the new
  // position (tunnelling). Resolving one brick pushes the ball out of the
  // rectangle, so the next brick in the same pass sees the pushed-out position:
  // a seam overlapping two bricks bounces exactly once (`vy = -vy` twice would
  // cancel out and let the ball through).
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    let hit = false;
    if (collides(ball, brick)) {
      resolveBrickOverlap(ball, brick);
      hit = true;
    } else if (resolveBrickSwept(ball, brick, prevX, prevY)) {
      hit = true;
    }
    if (!hit) continue;

    brick.alive = false;
    state.combo += 1;
    state.score += scoreForBrick(brick, state.combo);
  }

  // Exit through the bottom: ball lost
  if (ball.y - ball.r > HEIGHT) {
    return true;
  }
  return false;
}

